mapper.select:
SELECT e.id, e.author_user_id AS authorUserId, u.nickname AS authorName, u.avatar AS authorAvatar, ep.expertise AS authorExpertise, e.source AS source, e.title, e.summary, e.content_ref AS contentRefRaw, e.status, e.view_count AS viewCount, e.like_count AS likeCount, e.favorite_count AS favoriteCount, e.created_at AS createdAt FROM kb_entry e JOIN user u ON u.id = e.author_user_id LEFT JOIN expert_profile ep ON ep.user_id = e.author_user_id WHERE e.source = 'expert_post' AND e.author_user_id = #{authorUserId}
AND e.status = #{status}
AND (e.title LIKE CONCAT('%', #{keyword}, '%') OR e.summary LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY e.created_at DESC, e.id DESC
